# --- block: model ---
class Residual(nn.Module):
    def __init__(self, fn):
        super().__init__()
        self.fn = fn

    def forward(self, x):
        return self.fn(x) + x


class GELU(nn.Module):
    """Sigmoid approximation of GELU, as in Enformer and upstream PARM."""

    def forward(self, x):
        return torch.sigmoid(1.702 * x) * x


def ConvBlock(dim, dim_out=None, kernel_size=1):
    dim_out = dim if dim_out is None else dim_out
    return nn.Sequential(nn.BatchNorm1d(dim), GELU(), nn.Conv1d(dim, dim_out, kernel_size, padding=kernel_size // 2))


class AttentionPool(nn.Module):
    def __init__(self, dim, pool_size=2):
        super().__init__()
        self.pool_size = pool_size
        self.to_attn_logits = nn.Conv2d(dim, dim, 1, bias=False)

    def _pool(self, x):
        b, d, n = x.shape
        return x.reshape(b, d, n // self.pool_size, self.pool_size)

    def forward(self, x):
        b, _, n = x.shape
        remainder = n % self.pool_size
        needs_padding = remainder > 0
        if needs_padding:
            x = F.pad(x, (0, remainder), value=0)
            mask = torch.zeros((b, 1, n), dtype=torch.bool, device=x.device)
            mask = F.pad(mask, (0, remainder), value=True)
        x = self._pool(x)
        logits = self.to_attn_logits(x)
        if needs_padding:
            logits = logits.masked_fill(self._pool(mask), -torch.finfo(logits.dtype).max)
        attn = logits.softmax(dim=-1)
        return (x * attn).sum(dim=-1)


class PARM(nn.Module):
    def __init__(self, n_block=5, filter_size=125, vocab=4):
        super().__init__()
        kernel_size = 7
        self.stem = nn.Sequential(nn.Conv1d(vocab, filter_size, 7, padding="same"), Residual(ConvBlock(filter_size)),
                                  AttentionPool(filter_size, pool_size=2))
        layers = []
        initial, prev = filter_size, filter_size
        for block in range(n_block):
            if block > 4:
                filter_size = int(initial * 0.2)
            layers.append(nn.Sequential(ConvBlock(prev, filter_size, kernel_size=kernel_size),
                                        Residual(ConvBlock(filter_size, filter_size, kernel_size=1)),
                                        AttentionPool(filter_size, pool_size=2)))
            prev = filter_size
        self.conv_tower = nn.Sequential(*layers)
        self.linear1 = nn.Linear(filter_size, 1)
        self.relu = nn.ReLU()

    def forward(self, x):
        out = self.conv_tower(self.stem(x))
        out = torch.max(out, dim=-1).values
        return self.relu(self.linear1(out))


def build_model(input_len):
    """A torch.nn.Module: forward((B, 4, input_len) float one-hot) -> (B, 1) or (B,) predictions on the Log2RPM scale."""
    return PARM()

# --- block: input_pipeline ---
WIDTH = 600                 # the input window
TRAIN_ADAPTORS = True       # add the plasmid adaptors to training fragments
RANDOM_OFFSET = True        # training fragments at a uniformly random place in the window (else centred)
PREDICT_ADAPTORS = False    # add the adaptors at prediction (upstream does not)


def input_length():
    """The length of the input the model is given, so that build_model can size itself."""
    return WIDTH


def train_batch(codes, length, y, rng):
    """A training batch as the model sees it: codes (B, 600) uint8 and length (B,) on the GPU, y (B,), rng a numpy Generator.
    Returns (x, y)."""
    a5, a3 = (to_codes(ADAPTOR5, codes.device), to_codes(ADAPTOR3, codes.device)) if TRAIN_ADAPTORS else (None, None)
    free = WIDTH - laid_length(length, WIDTH, a5, a3)
    if RANDOM_OFFSET:
        g = torch.Generator(device=codes.device).manual_seed(int(rng.integers(2 ** 62)))
        left = (torch.rand(len(length), device=codes.device, generator=g) * (free + 1)).floor().long()
    else:
        left = (free + 1) // 2
    return onehot(arrange(codes, length, left, WIDTH, a5, a3)), y


def predict(net, codes, length):
    """Predictions for an evaluation batch, codes (B, 600) uint8 and length (B,) -> (B,) float. Called under torch.no_grad,
    net in eval mode."""
    a5, a3 = (to_codes(ADAPTOR5, codes.device), to_codes(ADAPTOR3, codes.device)) if PREDICT_ADAPTORS else (None, None)
    left = (WIDTH - laid_length(length, WIDTH, a5, a3) + 1) // 2      # centre (ceil), as upstream
    return net(onehot(arrange(codes, length, left, WIDTH, a5, a3))).float().reshape(-1)

# --- block: model ---
class GELU(nn.Module):
    def forward(self, x):
        return torch.sigmoid(1.702 * x) * x


class DilBlock(nn.Module):
    def __init__(self, ch, dil):
        super().__init__()
        self.f = nn.Sequential(nn.BatchNorm1d(ch), GELU(), nn.Conv1d(ch, ch, 3, padding=dil, dilation=dil),
                               nn.BatchNorm1d(ch), GELU(), nn.Conv1d(ch, ch, 1))

    def forward(self, x):
        return x + self.f(x)


class AnchoredNet(nn.Module):
    def __init__(self, input_len, ch=96, mid=64):
        super().__init__()
        self.stem = nn.Sequential(nn.Conv1d(4, ch, 15, padding=7), nn.BatchNorm1d(ch), GELU(), nn.MaxPool1d(2))
        self.trunk = nn.Sequential(*[DilBlock(ch, d) for d in (1, 2, 4, 8, 16, 32)])
        self.reduce = nn.Sequential(nn.MaxPool1d(2), nn.BatchNorm1d(ch), GELU(), nn.Conv1d(ch, mid, 5, padding=2),
                                    nn.BatchNorm1d(mid), GELU(), nn.MaxPool1d(2))
        with torch.no_grad():
            n = self.reduce(self.trunk(self.stem(torch.zeros(2, 4, input_len)))).numel() // 2
        self.head = nn.Sequential(nn.Flatten(), nn.Dropout(0.2), nn.Linear(n, 128), GELU(), nn.Linear(128, 1))
        for m in self.modules():
            if isinstance(m, (nn.Conv1d, nn.Linear)):
                nn.init.kaiming_normal_(m.weight, nonlinearity='relu')
                if m.bias is not None:
                    nn.init.zeros_(m.bias)
        self.head[-1].weight.data.mul_(0.1)
        nn.init.constant_(self.head[-1].bias, 2.6)

    def forward(self, x):
        out = self.head(self.reduce(self.trunk(self.stem(x))))
        return F.softplus(out.float()).reshape(-1)


def build_model(input_len):
    return AnchoredNet(input_len)

