class Stem(nn.Module):
    def __init__(self, c1=128, c=192):
        super().__init__()
        self.net = nn.Sequential(nn.Conv1d(4, c1, 15, padding=7), nn.BatchNorm1d(c1), nn.GELU(), nn.MaxPool1d(2),
                                 nn.Conv1d(c1, c, 5, padding=2), nn.BatchNorm1d(c), nn.GELU(), nn.MaxPool1d(2),
                                 nn.Conv1d(c, c, 3, padding=1), nn.BatchNorm1d(c), nn.GELU())

    def forward(self, x):
        return self.net(x)


class ConvBiGRU(nn.Module):
    def __init__(self, input_len, c=192, hidden=128, layers=2, heads=4):
        super().__init__()
        self.stem = Stem(128, c)
        self.drop_in = nn.Dropout(0.05)
        self.gru = nn.GRU(c, hidden, num_layers=layers, batch_first=True, bidirectional=True, dropout=0.1)
        d = 2 * hidden
        self.norm = nn.LayerNorm(d)
        self.heads = heads
        L = input_len // 4
        self.attn = nn.Linear(d, heads)
        self.pos_bias = nn.Parameter(torch.zeros(heads, L))
        self.head = nn.Sequential(nn.Linear(d * heads + d, 256), nn.GELU(), nn.Dropout(0.1), nn.Linear(256, 1))
        nn.init.constant_(self.head[-1].bias, 2.4)
        for name, p in self.gru.named_parameters():
            if 'weight_hh' in name:
                for i in range(0, p.shape[0], hidden):
                    nn.init.orthogonal_(p.data[i:i + hidden])
            elif 'weight_ih' in name:
                nn.init.xavier_uniform_(p.data)
            elif 'bias' in name:
                nn.init.zeros_(p.data)

    def forward(self, x):
        h = self.stem(x)                       # (B, c, L)
        h = self.drop_in(h.transpose(1, 2))    # (B, L, c)
        out, _ = self.gru(h)                   # (B, L, 2H)
        out = self.norm(out.float())
        L = out.shape[1]
        logits = self.attn(out).float().transpose(1, 2) + self.pos_bias[:, :L].unsqueeze(0)   # (B, heads, L)
        a = logits.softmax(dim=-1)
        pooled = torch.einsum('bld,bhl->bhd', out.float(), a).reshape(out.shape[0], -1)
        mx = out.float().max(dim=1).values
        z = torch.cat([pooled, mx], dim=1)
        y = self.head(z)
        return F.softplus(y.float()).reshape(-1)


def build_model(input_len):
    """A torch.nn.Module: forward((B, 4, input_len) float one-hot) -> (B,) predictions on the Log2RPM scale."""
    return ConvBiGRU(input_len)

