class GELU(nn.Module):
    def forward(self, x):
        return torch.sigmoid(1.702 * x) * x


class PairGrammar(nn.Module):
    """Factorised second-order motif interaction: z_i = u_i * sum_j K(i-j) v_j, per rank, with a learned asymmetric distance kernel."""

    def __init__(self, c, rank=96, span=61):
        super().__init__()
        self.u = nn.Conv1d(c, rank, 1)
        self.v = nn.Conv1d(c, rank, 1)
        self.kern = nn.Conv1d(rank, rank, span, padding=span // 2, groups=rank, bias=False)
        nn.init.normal_(self.kern.weight, 0.0, 1.0 / span)
        self.bn = nn.BatchNorm1d(rank)

    def forward(self, h):
        u = self.u(h)
        kv = self.kern(self.v(h))
        z = u.float() * kv.float()
        return self.bn(z)


class MotifPairNet(nn.Module):
    def __init__(self, input_len, c1=256, c=256, rank=96, local_ch=8, hidden=256):
        super().__init__()
        self.scan = nn.Sequential(nn.Conv1d(4, c1, 15, padding=7), nn.BatchNorm1d(c1), GELU(), nn.MaxPool1d(2),
                                  nn.Conv1d(c1, c, 5, padding=2), nn.BatchNorm1d(c), GELU(), nn.MaxPool1d(2))
        self.pair = PairGrammar(c, rank)
        self.mix = nn.Sequential(nn.Conv1d(c + rank, c, 1), nn.BatchNorm1d(c), GELU())
        L = (input_len // 2) // 2
        self.local = nn.Conv1d(c, local_ch, 1)
        self.head = nn.Sequential(nn.Linear(2 * c + 2 * rank + local_ch * L, hidden), GELU(), nn.Dropout(0.1),
                                  nn.Linear(hidden, 1))
        nn.init.constant_(self.head[-1].bias, 2.5)

    def forward(self, x):
        h = self.scan(x)
        z = self.pair(h)
        m = self.mix(torch.cat([h, z.to(h.dtype)], dim=1))
        g = torch.cat([m.max(dim=-1).values, m.mean(dim=-1), z.max(dim=-1).values.to(m.dtype),
                       z.mean(dim=-1).to(m.dtype)], dim=1)
        loc = self.local(m).flatten(1)
        out = self.head(torch.cat([g, loc], dim=1))
        return F.softplus(out.float()).reshape(-1)


def build_model(input_len):
    return MotifPairNet(input_len)

