class GELU(nn.Module):
    def forward(self, x):
        return torch.sigmoid(1.702 * x) * x


class DenseLayer(nn.Module):
    def __init__(self, cin, growth, d, drop=0.1):
        super().__init__()
        mid = 4 * growth
        self.bn1 = nn.BatchNorm1d(cin)
        self.conv1 = nn.Conv1d(cin, mid, 1)
        self.bn2 = nn.BatchNorm1d(mid)
        self.conv2 = nn.Conv1d(mid, growth, 3, padding=d, dilation=d)
        self.act = GELU()
        self.drop = nn.Dropout(drop)

    def forward(self, x):
        h = self.conv1(self.act(self.bn1(x)))
        h = self.conv2(self.act(self.bn2(h)))
        return torch.cat([x, self.drop(h)], dim=1)


class DenseBlock(nn.Module):
    def __init__(self, cin, growth, dilations, drop=0.1):
        super().__init__()
        layers = []
        c = cin
        for d in dilations:
            layers.append(DenseLayer(c, growth, d, drop))
            c += growth
        self.layers = nn.Sequential(*layers)
        self.out_ch = c

    def forward(self, x):
        return self.layers(x)


class DenseNet1D(nn.Module):
    def __init__(self, input_len, c0=96, growth=32, c_trans=160, local_ch=8, hidden=256):
        super().__init__()
        self.stem = nn.Sequential(nn.Conv1d(4, c0, 15, padding=7), nn.BatchNorm1d(c0), GELU(), nn.MaxPool1d(2))
        self.block1 = DenseBlock(c0, growth, (1, 2, 4, 8))
        c1 = self.block1.out_ch
        self.trans = nn.Sequential(nn.BatchNorm1d(c1), GELU(), nn.Conv1d(c1, c_trans, 1), nn.MaxPool1d(2))
        self.block2 = DenseBlock(c_trans, growth, (1, 2, 4, 8, 16, 32))
