class FSQ(nn.Module):
    """Finite scalar quantisation: each channel bounded by tanh and rounded to `levels` values (straight-through)."""

    def __init__(self, levels=7):
        super().__init__()
        self.half = (levels - 1) / 2.0

    def forward(self, x):
        dt = x.dtype
        z = torch.tanh(x.float()) * self.half
        q = torch.round(z)
        out = z + (q - z).detach()
        return (out / self.half).to(dt)


class TokenBlock(nn.Module):
    def __init__(self, c, d):
        super().__init__()
        self.n1 = nn.BatchNorm1d(c)
        self.c1 = nn.Conv1d(c, c, 3, padding=d, dilation=d)
        self.n2 = nn.BatchNorm1d(c)
        self.c2 = nn.Conv1d(c, c, 1)
        self.act = GELU()
        self.drop = nn.Dropout(0.05)
        nn.init.zeros_(self.c2.weight)
        nn.init.zeros_(self.c2.bias)

    def forward(self, x):
        h = self.c1(self.act(self.n1(x)))
        return x + self.c2(self.drop(self.act(self.n2(h))))


class FSQTokenNet(nn.Module):
    def __init__(self, input_len, c1=128, c2=192, qdim=48, levels=7, c=256, dilations=(1, 2, 4, 8, 16, 32),
