def shuffle(x, groups=2):
    b, c, n = x.shape
    return x.reshape(b, groups, c // groups, n).transpose(1, 2).reshape(b, c, n)


class SplitUnit(nn.Module):
    """ShuffleNetV2 basic unit: split channels, transform one half, concat, shuffle."""

    def __init__(self, c, d=1, k=7):
        super().__init__()
        h = c // 2
        self.b = nn.Sequential(
            nn.Conv1d(h, h, 1, bias=False), nn.BatchNorm1d(h), GELU(),
            nn.Conv1d(h, h, k, padding=d * (k // 2), dilation=d, groups=h, bias=False), nn.BatchNorm1d(h),
            nn.Conv1d(h, h, 1, bias=False), nn.BatchNorm1d(h), GELU())

    def forward(self, x):
        x1, x2 = x.chunk(2, dim=1)
        return shuffle(torch.cat([x1, self.b(x2)], dim=1), 2)


class DownUnit(nn.Module):
    """ShuffleNetV2 downsampling unit (max-pool by 2), cin -> cout."""

    def __init__(self, cin, cout, k=5):
        super().__init__()
        h = cout // 2
        self.left = nn.Sequential(
            nn.Conv1d(cin, cin, k, padding=k // 2, groups=cin, bias=False), nn.BatchNorm1d(cin), nn.MaxPool1d(2),
            nn.Conv1d(cin, h, 1, bias=False), nn.BatchNorm1d(h), GELU())
        self.right = nn.Sequential(
            nn.Conv1d(cin, h, 1, bias=False), nn.BatchNorm1d(h), GELU(),
            nn.Conv1d(h, h, k, padding=k // 2, groups=h, bias=False), nn.BatchNorm1d(h), nn.MaxPool1d(2),
            nn.Conv1d(h, h, 1, bias=False), nn.BatchNorm1d(h), GELU())

    def forward(self, x):
        return shuffle(torch.cat([self.left(x), self.right(x)], dim=1), 2)


class ShuffleV2Net(nn.Module):
    def __init__(self, input_len, c0=128, c1=256, c2=384, local_ch=4, hidden=256,
                 dilations=(1, 2, 4, 8, 16, 1, 2, 4, 8, 16)):
        super().__init__()
        self.stem = nn.Sequential(nn.Conv1d(4, c0, 15, padding=7), nn.BatchNorm1d(c0), GELU())
        self.s1 = nn.Sequential(DownUnit(c0, c1), SplitUnit(c1, 1), SplitUnit(c1, 2))
        self.s2 = nn.Sequential(DownUnit(c1, c2), *[SplitUnit(c2, d) for d in dilations])
        self.post = nn.Sequential(nn.BatchNorm1d(c2), GELU())
        L2 = (input_len // 2) // 2
        self.attn = nn.Conv1d(c2, 1, 1)
        self.pos_bias = nn.Parameter(torch.zeros(1, 1, L2))
        self.local = nn.Conv1d(c2, local_ch, 1)
        self.head = nn.Sequential(nn.Linear(3 * c2 + local_ch * L2, hidden), GELU(), nn.Dropout(0.1),
                                  nn.Linear(hidden, 1))
        nn.init.constant_(self.head[-1].bias, 2.6)

    def forward(self, x):
        u = self.post(self.s2(self.s1(self.stem(x))))
        logits = self.attn(u).float() + self.pos_bias.float()
        w = torch.softmax(logits, dim=-1)
        uf = u.float()
        pooled = (uf * w).sum(dim=-1)
        g = torch.cat([uf.max(dim=-1).values, uf.mean(dim=-1)], dim=1)
        loc = self.local(u).flatten(1).float()
        feats = torch.cat([pooled, g, loc], dim=1).to(u.dtype)
        out = self.head(feats)
        return F.softplus(out.float()).reshape(-1)


