class BlurPool(nn.Module):
    """Anti-aliased stride-2 downsampling: fixed binomial [1,2,1]/4 depthwise filter."""

    def __init__(self, c):
        super().__init__()
        self.c = c
        self.register_buffer("filt", torch.tensor([1.0, 2.0, 1.0]).view(1, 1, 3) / 4.0, persistent=False)

    def forward(self, x):
        w = self.filt.to(x.dtype).expand(self.c, 1, 3)
        x = F.pad(x, (1, 1), mode="replicate")
        return F.conv1d(x, w, stride=2, groups=self.c)


class MaxBlurPool(nn.Module):
    def __init__(self, c):
        super().__init__()
        self.blur = BlurPool(c)

    def forward(self, x):
        x = F.max_pool1d(F.pad(x, (0, 1), mode="replicate"), 2, 1)
        return self.blur(x)


class ResBlock(nn.Module):
    def __init__(self, c, k=3, d=1, drop=0.05):
